import sys
from collections import defaultdict

input = sys.stdin.read().split()
n = int(input[0])
m = int(input[1])
a = list(map(int, input[2:2+n]))
edges = [(int(input[2+n+2*i]), int(input[2+n+2*i+1])) for i in range(n-1)]
queries = [(int(input[2+n+2*(n-1)+2*i]), int(input[2+n+2*(n-1)+2*i+1])) if input[2+n+2*(n-1)+2*i] == '1' else (int(input[2+n+2*(n-1)+2*i]),) for i in range(m)]

children = defaultdict(list)
for v, u in edges:
    children[v].append(u)
    children[u].append(v)

values = a[:]
parent = {1: None}
stack = [1]
while stack:
    node = stack.pop()
    for child in children[node]:
        if child != parent[node]:
            parent[child] = node
            stack.append(child)

def update(node, val):
    values[node-1] += val
    for child in children[node]:
        if child != parent[node]:
            update(child, -val)

query_results = []
for query in queries:
    if query[0] == 1:
        update(query[1], query[2])
    else:
        query_results.append(values[query[1]-1])

for result in query_results:
    print(result)
